void WritePoint3DWithVariableBitNumber(vec3 point, tolerance) {
    Vec3Int ipoint = Vec3IntRound(point, tolerance);
	unsigned nbits = NumBitsToStoreVec3Int(ipoint);
	WriteUnsignedIntegerWithVariableBitNumber(nbits);
