```c++
if (is_trimmed)
{
    // reading loops
    CompressedEntityType curveType = PRC_HCG_NewLoop;
    while (curveType == PRC_HCG_NewLoop)
    {
        startNewLoop();
        loop_surface_orienttion = readBit();
        // here we read curves that compose the loop
        do
        {
            // Table "RefOrCompressedCurve"
            curve_is_not_already_stored = readBit();
            if (curve_is_not_already_stored)
            {
                curveType = readCompressEntityType(); // position in the buffer
                if ((curveType == PRC_HCG_NewLoop) || (curveType == PRC_HCG_EndLoop))
                    break;
                readCompressedCurveOfType(curveType);
            }
            else
            {
                readCurveRef();
            }
            addCurveToTheLoop();
        } while (true);
        storeTheLoop();
    }
}
